"""Write the audited public/pending inventory and per-reservoir check table."""
import json
from pathlib import Path
from backend.config import DATA,ROOT
from backend.active import monitoring
from backend.monitoring import reservoirs
from backend.readiness import check
rows=reservoirs();pending=json.loads((DATA/'internal/pending-reservoirs.json').read_text())
frontend=json.loads((ROOT/'output/public-frontend-state-verification.json').read_text())
spectral=json.loads((ROOT/'output/processing-verification.json').read_text())
verified={r['reservoir_id']:r for r in spectral}
lines=['# NEERWATCH public inventory repair — 22 October 2026','','## Counts','','- Public reservoirs: '+str(len(rows)),f"- Removed unwanted tank names: {sum('tank' in r['name'].lower() for r in pending)}.",'- Excluded coordinate-only CWC inventory entries: 23 (20 tanks and 3 other entries).',f'- Total internal pending records: {len(pending)}; no public detail, image, report, boundary, processing or export access.',f'- Public verified water polygons: {len(rows)}.',f'- Public reservoirs with valid Sentinel-2 concentration/category: {len(rows)}.',f'- Public reservoirs with two compatible acquisition dates and valid percentage change: {len(rows)}.',f'- Public reservoirs with matching true-colour image, chlorophyll map and GeoTIFF: {len(rows)}.','- Public Sentinel-2 observation records: '+str(sum(len(monitoring(r['id'])['history']) for r in rows))+'.','','## Per-reservoir verification','','PASS here refers to actual geometry, saved spectral data, live API and executed React/Leaflet state checks. Visual layout/geographic overlay inspection remains incomplete because browser control is disabled. No row is claimed visually verified in this repair.','','| Reservoir | Identity / polygon provenance | Location / CRS | Boundary rendered / popup / polygon click | Valid S2 / EPA | Two dates / change | RGB / map / scene match | React auto-load / navigation | Restart / fresh DOM | Visual browser |','|---|---|---|---|---|---|---|---|---|']
for r in rows:
 assert check(r)['ready'];assert verified[r['id']]['spectral_array_and_geotiff_verified']
 ui=[x for x in frontend if x['reservoir']==r['id']];assert len(ui)==2 and all(x['polygon_popup_and_click']=='PASS' for x in ui)
 lines.append(f"| {r['name']} | PASS | PASS | PASS (DOM) | PASS | PASS | PASS | PASS | PASS | INCOMPLETE |")
lines+=['','## Real observation values','','All values are experimental Gilerson 2010 two-band Sentinel-2 L2A BOA screening estimates, not laboratory measurements. No concentration was hardcoded, copied from KRS or substituted from Sentinel-3.','','| Reservoir | Earlier UTC date | Earlier µg/L | Latest UTC date | Latest µg/L | Change | EPA category |','|---|---|---:|---|---:|---:|---|']
for r in rows:
 m=monitoring(r['id']);a=m['previous'];b=m['latest'];lines.append(f"| {r['name']} | {a['observed_at']} | {a['chlorophyll_a']:.5f} | {b['observed_at']} | {b['chlorophyll_a']:.5f} | {m['change']['percent']:+.3f}% | {m['classification']['name']} |")
lines+=['','## Boundary evidence','','All public boundaries are existing OpenStreetMap water polygons (ODbL), an established geospatial source, not circles or dam coordinates. The polygons were checked for topology, geographic location against registered reservoir coordinates, Karnataka-region bounds, Sentinel-2 overlap, water-mask pixels and EPSG:32643 raster consistency. Saved record source URLs and original boundary source metadata are retained. These are not represented as surveyed government cadastral boundaries.','','| Reservoir | Water polygon source |','|---|---|']
for r in rows:lines.append(f"| {r['name']} | {r['osm_url']} |")
lines+=['','## What changed','','The public source data/reservoirs.json now contains only operational records. Excluded records and reasons are retained under data/internal/pending-reservoirs.json, which is not mounted as a static directory or exposed through the API. Public inventory is additionally gated on evidence at request time. All public reservoir routes, exports and reports derive from that filtered registry; direct access to pending IDs is rejected with HTTP 404.','','Same-method pairing now also checks atmospheric correction, analysis resolution, shoreline/cloud buffers, minimum pixel/coverage settings, algorithm range and aggregation, and requires different acquisition dates. A positive earlier value is required for percentage change.','','Map selection draws the selected real polygon, fits its bounds, highlights it, names it in a popup and handles polygon clicks using the same workspace selection callback as the list. Existing colors/layout were retained.','','Vani Vilasa uses the existing consistent ID vani-vilasa in selector, detail API and cache directory. Its persisted concentration, dates and percentage load on selection and in fresh React sessions. No new processing click is needed.','','Kabini and Harangi were processed sequentially in small batches (two observations each), verified and admitted. Hemavathi, Almatti, Linganamakki and other incomplete entries remain pending; expanding them was not allowed to keep them on the public site before readiness.','','## Exact changed/added implementation and test files','','- data/reservoirs.json','- data/internal/pending-reservoirs.json','- backend/readiness.py','- backend/active.py','- backend/monitoring.py','- backend/main.py','- frontend/src/main.jsx','- pipeline/sentinel2_chlorophyll.py (internal-only pending lookup for batch preprocessing)','- scripts/verify_live_processing.py','- scripts/report_public_readiness.py','- scripts/frontend-check/check.mjs','- scripts/frontend-check/package.json','- tests/test_public_readiness.py','- tests/test_system.py (replace obsolete minimum-count expectation with operational registry checks)','- tests/test_sentinel2.py (replace obsolete 40-entry expectation with strict public inventory checks)','- IMPLEMENTATION.md','- data/sentinel2/kabini/* and data/sentinel2/harangi/* (genuine new scenes, arrays, manifests, images and rasters)','','## Tests and reproducible evidence','','- Backend suite: 51 passed; one pre-existing Starlette/httpx deprecation warning.','- Frontend production build: passed.','- Backend restarted; all public inventory/results loaded from persisted data afterward.','- Real React bundle and real Leaflet executed against the running API in jsdom: 16 successful workspace loads across two fresh DOM sessions. Each loaded nonempty concentration/date/category/change and a real image URL. Polygon SVG, popup name and click callback passed for every reservoir. This is frontend state/integration evidence, not a visual browser screenshot or layout test.','- All pending IDs checked for HTTP 404 on detail, boundary, processing status, processing POST, images and reports; pending names absent from CSV export.','- Live spectral audit checked each public reservoir concentration against saved band arrays and GeoTIFF pixels, metadata CRS, source scene IDs, images and EPA category.','- Evidence: output/processing-verification.json and output/public-frontend-state-verification.json.','- Frontend test dependencies: install in scripts/frontend-check with npm install, then npm test. The test expects the backend at http://127.0.0.1:8010.','','## Remaining limitations','','Browser control is disabled in Work settings. Final visual layout/overlay inspection is incomplete; the site is not claimed fully visually verified. The application remains running locally at http://127.0.0.1:8010; no external production deployment was supplied or changed.','','Full ACOLITE water-specific correction and local field calibration are still absent. Satellite-derived chlorophyll-a estimates have not yet been validated against Karnataka field measurements. EPA categories describe trophic screening, not toxicity or water safety. No synthetic data were added.','','## Pending inventory','','| Record | Pending reason |','|---|---|']
for r in pending:lines.append(f"| {r['name']} | {'; '.join(r.get('pending_reasons',[]))} |")
(ROOT/'output/public-inventory-repair-report.md').write_text('\n'.join(lines)+'\n')
print('Report written:',len(rows),'public,',len(pending),'pending')
